-- In-memory test fixture only: original document tables as observed through read-only metadata.
CREATE TABLE public.whatsapp_web_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),provider text NOT NULL DEFAULT 'evolution',status text NOT NULL DEFAULT 'conectado',metadata jsonb NOT NULL DEFAULT '{}');
CREATE TABLE public.slim_order_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL UNIQUE,workspace_id uuid NOT NULL,version integer NOT NULL DEFAULT 1 CHECK(version=1),sha256 text NOT NULL CHECK(sha256 ~ '^[0-9a-f]{64}$'),filename text NOT NULL,pdf_base64 text NOT NULL CHECK(length(pdf_base64) BETWEEN 20 AND 4000000),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),FOREIGN KEY(order_id,workspace_id) REFERENCES public.slim_orders(id,workspace_id));
CREATE TABLE public.slim_order_document_deliveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),document_id uuid NOT NULL REFERENCES public.slim_order_documents(id),request_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES auth.users(id),session_id uuid NOT NULL REFERENCES public.whatsapp_web_sessions(id),phone text NOT NULL CHECK(phone ~ '^[+][1-9][0-9]{7,14}$'),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected','uncertain')),message_id text,last_error text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),finished_at timestamptz,UNIQUE(workspace_id,request_id));
CREATE UNIQUE INDEX slim_document_one_unresolved_delivery ON public.slim_order_document_deliveries(document_id) WHERE status IN ('pending','uncertain');
